import sys, csv, json, datetime

def parse_timestamp(ts: str) -> datetime.datetime:
    # fromisoformat handles ISO-8601 with offset
    dt = datetime.datetime.fromisoformat(ts)
    return dt.astimezone(datetime.timezone.utc)

def main():
    if len(sys.argv) != 2:
        sys.stderr.write('Usage: python3 reconcile.py <path_to_csv>\n')
        sys.exit(1)
    path = sys.argv[1]
    # Mapping tx_id -> (utc_dt, status, amount)
    records = {}
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            tx_id = row['tx_id']
            utc_dt = parse_timestamp(row['timestamp'])
            status = row['status']
            # amount may be empty for non‑VALID rows; convert safely
            amount = float(row['amount']) if row['amount'] else 0.0
            if tx_id not in records:
                records[tx_id] = (utc_dt, status, amount)
                continue
            cur_dt, cur_status, cur_amount = records[tx_id]
            if utc_dt > cur_dt:
                records[tx_id] = (utc_dt, status, amount)
            elif utc_dt == cur_dt:
                # tie‑breaker: alphabetical order of status (FAILED < PENDING < VALID)
                if status < cur_status:
                    records[tx_id] = (utc_dt, status, amount)
    total_valid = 0.0
    valid_count = 0
    failed_count = 0
    for utc_dt, status, amount in records.values():
        if status == 'VALID':
            valid_count += 1
            total_valid += amount
        elif status == 'FAILED':
            failed_count += 1
        # PENDING rows are ignored
    total_valid = round(total_valid, 2)
    result = {
        "total_valid_amount": total_valid,
        "valid_count": valid_count,
        "failed_count": failed_count
    }
    # Compact JSON without extra spaces
    print(json.dumps(result, separators=(',', ':')))

if __name__ == '__main__':
    main()
